package com.johnny.hotel;
import com.johnny.hotel.support.WalletDevelopmentGuard;import org.flywaydb.core.Flyway;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfSystemProperty;import org.springframework.boot.builder.SpringApplicationBuilder;import java.sql.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
@EnabledIfSystemProperty(named="hotel.v61.fresh.smoke",matches="true") class V58FreshMigrationSmokeTest {
 @Test void zeroUserFreshV1ThroughV61()throws Exception{var settings=WalletDevelopmentGuard.settings();String database="hotel_v61_smoke_"+UUID.randomUUID().toString().replace("-","").substring(0,12),original=WalletDevelopmentGuard.url(),temporary=original.replace("/hotel_management?","/"+database+"?");try(var admin=DriverManager.getConnection(original,settings.get("DB_USERNAME"),settings.get("DB_PASSWORD"));var statement=admin.createStatement()){statement.execute("CREATE DATABASE `"+database+"` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci");try{var flyway=Flyway.configure().dataSource(temporary,settings.get("DB_USERNAME"),settings.get("DB_PASSWORD")).locations("classpath:db/migration").load();var result=flyway.migrate();flyway.validate();try(var c=DriverManager.getConnection(temporary,settings.get("DB_USERNAME"),settings.get("DB_PASSWORD"));var s=c.createStatement();var r=s.executeQuery("SELECT (SELECT COUNT(*) FROM flyway_schema_history WHERE success=1 AND version='61'),(SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name IN ('attendance_session','attendance_punch','attendance_correction_request','leave_type','leave_allocation','employee_leave_request','task_eligible_role','workforce_approval_config','employee_compensation_profile','payroll_policy','payroll_period','payroll_payslip','payroll_payment'))")){assertTrue(r.next());assertEquals(1,r.getInt(1));assertEquals(13,r.getInt(2));assertTrue(result.migrationsExecuted>0);}try(var context=new SpringApplicationBuilder(HotelBackendApplication.class).run("--spring.datasource.url="+temporary,"--spring.datasource.username="+settings.get("DB_USERNAME"),"--spring.datasource.password="+settings.get("DB_PASSWORD"),"--spring.data.redis.password="+settings.get("REDIS_PASSWORD"),"--server.port=0","--logging.level.org.springframework=WARN")){assertTrue(context.isActive());}}finally{statement.execute("DROP DATABASE `"+database+"`");}}}
}
